//! Golden tests for the Phase 12 calculators.
//!
//! * M/M/c (Erlang C) queues against exact rational values
//!   (`fixtures/queueing.json`, generated by `fixtures/generators/queueing.py`)
//!   and the County Hospital example published in Hillier and Lieberman,
//!   *Introduction to Operations Research*.
//! * CASPER weighted proportions with Taylor-series cluster variance against
//!   the `samplics` Python package (`fixtures/survey.json`, generated by
//!   `fixtures/generators/survey.py`).

use phn_epi::queueing::{erlang_c, mmc};
use phn_epi::survey::weighted_proportions;

#[derive(serde::Deserialize)]
struct QCase {
    servers: u32,
    arrival_rate: f64,
    service_rate: f64,
    prob_wait: f64,
    mean_queue: f64,
    mean_wait: f64,
    mean_time_in_system: f64,
    mean_in_system: f64,
}

#[derive(serde::Deserialize)]
struct QFixture {
    cases: Vec<QCase>,
    published: Vec<QCase>,
}

fn rel(a: f64, b: f64) -> f64 {
    if b.abs() < 1e-300 {
        a.abs()
    } else {
        ((a - b) / b).abs()
    }
}

fn check(c: &QCase, tol: f64) {
    let m = mmc(c.servers, c.arrival_rate, c.service_rate).unwrap();
    for (got, want, what) in [
        (m.prob_wait, c.prob_wait, "P(wait)"),
        (m.mean_queue, c.mean_queue, "Lq"),
        (m.mean_wait, c.mean_wait, "Wq"),
        (m.mean_time_in_system, c.mean_time_in_system, "W"),
        (m.mean_in_system, c.mean_in_system, "L"),
    ] {
        assert!(
            rel(got, want) < tol,
            "c={} λ={} μ={}: {what} {got} vs {want}",
            c.servers,
            c.arrival_rate,
            c.service_rate
        );
    }
    let a = c.arrival_rate / c.service_rate;
    assert!(rel(erlang_c(c.servers, a), c.prob_wait) < tol);
}

#[test]
fn erlang_c_matches_exact_rational_values() {
    let f: QFixture = serde_json::from_str(include_str!("fixtures/queueing.json")).unwrap();
    assert!(f.cases.len() >= 80);
    for c in &f.cases {
        check(c, 1e-9);
    }
}

#[test]
fn erlang_c_matches_the_published_county_hospital_example() {
    let f: QFixture = serde_json::from_str(include_str!("fixtures/queueing.json")).unwrap();
    for c in &f.published {
        check(c, 1e-12);
    }
    // Rounded values as printed: s = 2 gives L = 0.75, Lq = 0.083, W = 0.375 h, Wq = 0.042 h.
    let m = mmc(2, 2.0, 3.0).unwrap();
    assert_eq!(format!("{:.3}", m.mean_queue), "0.083");
    assert_eq!(format!("{:.3}", m.mean_wait), "0.042");
    assert_eq!(format!("{:.3}", m.mean_time_in_system), "0.375");
    assert_eq!(format!("{:.2}", m.mean_in_system), "0.75");
}

#[derive(serde::Deserialize)]
struct SCat {
    category: String,
    n: usize,
    weighted_count: f64,
    proportion: f64,
    stderror: f64,
}

#[derive(serde::Deserialize)]
struct SFixture {
    cluster: Vec<usize>,
    weight: Vec<f64>,
    answer: Vec<Option<usize>>,
    labels: Vec<String>,
    estimates: Vec<SCat>,
}

#[test]
fn casper_proportions_match_samplics_taylor_estimates() {
    let f: SFixture = serde_json::from_str(include_str!("fixtures/survey.json")).unwrap();
    let t = weighted_proportions(&f.cluster, &f.weight, &f.answer, &f.labels, 0.95).unwrap();
    assert_eq!(t.categories.len(), f.estimates.len());
    for e in &f.estimates {
        let got = t
            .categories
            .iter()
            .find(|c| c.category == e.category)
            .unwrap();
        assert_eq!(got.n, e.n, "{}", e.category);
        assert!(
            rel(got.weighted_count, e.weighted_count) < 1e-9,
            "{}",
            e.category
        );
        assert!(
            rel(got.percent / 100.0, e.proportion) < 1e-9,
            "{}",
            e.category
        );
        assert!(
            rel(got.se_percent / 100.0, e.stderror) < 1e-6,
            "{}: SE {} vs {}",
            e.category,
            got.se_percent / 100.0,
            e.stderror
        );
    }
}
